def seed_tontine_method(apps, schema_editor):
    """Moyen de paiement « Tontine scolaire » : imputation, à la caisse, des versements d'une tontine."""
    method = apps.get_model("sales", "PaymentMethod")
    counter = apps.get_model("core", "SyncCounter")
    if method.objects.filter(code="TONTINE").exists():
        return
    row, _ = counter.objects.get_or_create(name="global", defaults={"value": 0})
    row.value += 1
    row.save(update_fields=["value"])
    method.objects.create(id=uuid.uuid4(), code="TONTINE", label="Tontine scolaire", kind="TONTINE",
                          requires_reference=False, sort_order=110, sync_version=row.value)


